import React, { useRef, useEffect } from 'react';

const VARIANTS = {
  dark:  { base:'#18161e', mid:'#28243a', light:'#38324e', spec:'rgba(255,255,255,0.5)',  glow:'rgba(80,70,120,0.15)' },
  slate: { base:'#1a1e2a', mid:'#252c40', light:'#323a52', spec:'rgba(255,255,255,0.45)', glow:'rgba(50,70,130,0.15)' },
  dusk:  { base:'#221820', mid:'#342430', light:'#463040', spec:'rgba(255,255,255,0.42)', glow:'rgba(100,50,100,0.15)' },
  moss:  { base:'#181e16', mid:'#242e20', light:'#303e2c', spec:'rgba(255,255,255,0.4)',  glow:'rgba(50,100,40,0.15)' },
  ember: { base:'#221410', mid:'#341e14', light:'#46281c', spec:'rgba(255,255,255,0.38)', glow:'rgba(120,50,30,0.15)' },
  storm: { base:'#16181e', mid:'#22262e', light:'#2e343e', spec:'rgba(255,255,255,0.44)', glow:'rgba(60,80,120,0.15)' },
};

export default function Orb3D({ size = 300, variant = 'dark', speed = 0.4, morphing = true }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    // Set canvas pixel size = CSS size (no DPR scaling — that was shrinking it)
    canvas.width  = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    const c = VARIANTS[variant] || VARIANTS.dark;

    const draw = () => {
      t.current += 0.005 * speed;
      ctx.clearRect(0, 0, size, size);
      const cx = size / 2, cy = size / 2;
      const r  = size * 0.42;

      // Morphing outline
      ctx.beginPath();
      for (let i = 0; i <= 80; i++) {
        const a = (i / 80) * Math.PI * 2;
        const wr = morphing
          ? r + Math.sin(a * 3 + t.current * 0.7)  * r * 0.05
              + Math.cos(a * 5 + t.current * 1.0)  * r * 0.022
              + Math.sin(a * 7 + t.current * 0.45) * r * 0.012
          : r;
        const x = cx + Math.cos(a) * wr;
        const y = cy + Math.sin(a) * wr;
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.save();
      ctx.clip();

      // Base dark gradient
      const base = ctx.createRadialGradient(cx - r*0.1, cy - r*0.15, 0, cx, cy, r * 1.05);
      base.addColorStop(0,    c.light);
      base.addColorStop(0.4,  c.mid);
      base.addColorStop(0.8,  c.base);
      base.addColorStop(1,    '#0a0810');
      ctx.fillStyle = base;
      ctx.fillRect(0, 0, size, size);

      // Slow internal glow
      const lx = cx + Math.sin(t.current * 0.5) * r * 0.22;
      const ly = cy + Math.cos(t.current * 0.4) * r * 0.18;
      const inner = ctx.createRadialGradient(lx, ly, 0, lx, ly, r * 0.75);
      inner.addColorStop(0,   'rgba(200,190,255,0.14)');
      inner.addColorStop(0.6, 'rgba(160,150,220,0.04)');
      inner.addColorStop(1,   'transparent');
      ctx.fillStyle = inner;
      ctx.fillRect(0, 0, size, size);

      // Subtle surface noise blobs
      for (let i = 0; i < 5; i++) {
        const bx = cx + Math.sin(t.current * 0.22 + i * 1.3) * r * 0.38;
        const by = cy + Math.cos(t.current * 0.28 + i * 1.0) * r * 0.32;
        const br = r * (0.14 + Math.sin(t.current * 0.5 + i) * 0.03);
        const bg = ctx.createRadialGradient(bx, by, 0, bx, by, br);
        bg.addColorStop(0, 'rgba(255,255,255,0.05)');
        bg.addColorStop(1, 'transparent');
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, size, size);
      }

      // Deep shadow bottom-right
      const shadow = ctx.createRadialGradient(cx + r*0.35, cy + r*0.4, 0, cx + r*0.35, cy + r*0.4, r * 0.85);
      shadow.addColorStop(0, 'rgba(0,0,0,0.65)');
      shadow.addColorStop(1, 'transparent');
      ctx.fillStyle = shadow;
      ctx.fillRect(0, 0, size, size);

      // Sharp specular highlight top-left
      const hx = cx - r * (0.22 + Math.sin(t.current * 0.28) * 0.04);
      const hy = cy - r * (0.25 + Math.cos(t.current * 0.22) * 0.04);
      const spec = ctx.createRadialGradient(hx, hy, 0, hx, hy, r * 0.3);
      spec.addColorStop(0,   c.spec);
      spec.addColorStop(0.3, 'rgba(255,255,255,0.08)');
      spec.addColorStop(0.7, 'rgba(255,255,255,0.01)');
      spec.addColorStop(1,   'transparent');
      ctx.fillStyle = spec;
      ctx.fillRect(0, 0, size, size);

      // Rim light left edge
      const rim = ctx.createRadialGradient(cx - r*0.88, cy, 0, cx - r*0.88, cy, r * 0.38);
      rim.addColorStop(0, 'rgba(200,210,255,0.1)');
      rim.addColorStop(1, 'transparent');
      ctx.fillStyle = rim;
      ctx.fillRect(0, 0, size, size);

      ctx.restore();

      // Dashed orbit ring
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(t.current * 0.18);
      ctx.scale(1, 0.28);
      ctx.beginPath();
      ctx.arc(0, 0, r * 1.22, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.lineWidth = 1.5;
      ctx.setLineDash([4, 10]);
      ctx.stroke();
      ctx.restore();

      // Ground shadow ellipse
      const gg = ctx.createRadialGradient(cx, cy + r * 0.92, 0, cx, cy + r * 0.92, r * 0.6);
      gg.addColorStop(0, 'rgba(0,0,0,0.2)');
      gg.addColorStop(1, 'transparent');
      ctx.beginPath();
      ctx.ellipse(cx, cy + r * 0.93, r * 0.58, r * 0.13, 0, 0, Math.PI * 2);
      ctx.fillStyle = gg;
      ctx.fill();

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, variant, speed, morphing]);

  // CSS size matches canvas pixel size exactly
  return (
    <canvas
      ref={canvasRef}
      style={{ display:'block', width:`${size}px`, height:`${size}px` }}
    />
  );
}
